package org.apache.commons.math3.genetics;

import org.junit.Test;
import org.junit.Assert;
import java.util.Iterator;
import java.util.List;
import java.util.ArrayList;

public class AgentBRT_Math_34_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Create a list of chromosomes
        List<Chromosome> chromosomes = new ArrayList<>();
        chromosomes.add(new DummyChromosome(1));
        chromosomes.add(new DummyChromosome(2));

        // Create an ElitisticListPopulation with the chromosomes
        ElitisticListPopulation population = new ElitisticListPopulation(chromosomes, 10, 0.5);

        // Get the iterator
        Iterator<Chromosome> iterator = population.iterator();

        // Attempt to remove an element using the iterator
        try {
            iterator.remove();
            Assert.fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected exception
        }
    }

    // Dummy Chromosome class for testing purposes
    private static class DummyChromosome extends Chromosome {
        private final double fitness;

        public DummyChromosome(double fitness) {
            this.fitness = fitness;
        }

        @Override
        public double fitness() {
            return fitness;
        }
    }
}

