package org.apache.commons.math3.genetics;

import org.junit.Test;
import org.junit.Assert;
import java.util.Iterator;
import java.util.List;
import java.util.ArrayList;

public class AgentBRT_Math_34_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Create a list of chromosomes
        List<Chromosome> chromosomes = new ArrayList<>();
        chromosomes.add(new DummyChromosome(1));
        chromosomes.add(new DummyChromosome(2));

        // Create a ListPopulation with the chromosomes
        ListPopulation population = new ListPopulation(chromosomes, 10);

        // Get the iterator
        Iterator<Chromosome> iterator = population.iterator();

        // Check if the iterator has the correct number of elements
        int count = 0;
        while (iterator.hasNext()) {
            iterator.next();
            count++;
        }

        // The expected count should match the size of the chromosomes list
        Assert.assertEquals("Iterator should iterate over all chromosomes", chromosomes.size(), count);
    }

